WITH outside_relations AS (SELECT n.nspname,c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner) AS owner,c.relacl::text AS acl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','auth') AND c.oid<>'public.users'::regclass), all_policies AS(SELECT * FROM pg_policies WHERE schemaname IN ('public','auth')), other_functions AS(SELECT n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) AS args,p.prosecdef,pg_get_userbyid(p.proowner) AS owner,p.proacl::text AS acl,p.proconfig,md5(pg_get_functiondef(p.oid)) AS definition_hash FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','auth') AND p.prokind='f' AND NOT(p.oid=ANY(ARRAY['public.create_onboarding_user(text,text,text)'::regprocedure,'public.onboard_tenant(text,text,text,text,uuid,text,text)'::regprocedure]))) SELECT jsonb_build_object('outside_relations_count',(SELECT count(*) FROM outside_relations),'outside_relation_hash',(SELECT md5(jsonb_agg(to_jsonb(r) ORDER BY nspname,relname)::text) FROM outside_relations r),'all_policy_hash',(SELECT md5(jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname)::text) FROM all_policies p),'other_function_hash',(SELECT md5(jsonb_agg(to_jsonb(f) ORDER BY nspname,proname,args)::text) FROM other_functions f),'full_membership_hash',(SELECT md5(jsonb_agg(to_jsonb(m) ORDER BY roleid,member,grantor)::text) FROM pg_auth_members m),'full_role_hash',(SELECT md5(jsonb_agg((to_jsonb(r)-'rolvaliduntil') ORDER BY rolname)::text) FROM pg_roles r),'schema_acl_hash',(SELECT md5(jsonb_agg(jsonb_build_object('schema',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text) ORDER BY nspname)::text) FROM pg_namespace WHERE nspname NOT LIKE 'pg_temp_%' AND nspname NOT LIKE 'pg_toast_temp_%'),'default_acl_hash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(a) ORDER BY oid)::text,'[]')) FROM pg_default_acl a)) AS evidence;
